{
  "description": "The creature is a quadrupedal, bear-like mammal shown in right-facing profile against a plain light background. Its body is covered in dense, shaggy brown fur that is lighter cream on the chest and belly and darker on the legs and back. Integrated into the fur are multiple glossy, dark brown to black, hard chitinous structures resembling beetle exoskeleton, including a large curved horn on the forehead, a large plate on the shoulder/neck, and several ridged, wing-cover-like plates on the back and sides. The animal stands on four thick legs ending in clawed paws and has a small furry tail at the rear. No wings, tentacles, or additional limbs are visible.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with an elongated snout, black nose, small dark eye, and mouth with lower lip visible, covered in brown fur with lighter fur around the muzzle",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large, glossy black, upward-curving horn with two small pointed tines on the inner curve and a bulbous base where it meets the fur",
      "where": "projecting upward and forward from the center of the forehead on top of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry ears covered in dense brown fur",
      "where": "on top of the head behind the horn, one slightly in front of the other"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred, columnar legs covered in long brown fur, with glossy dark brown joint plates visible at the upper and lower joints",
      "where": "two under the front chest/shoulder and two under the rear hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with furry tops, visible long curved light-brown claws on the toes, and dark pads underneath",
      "where": "at the bottom ends of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small, short, rounded tuft of brown fur",
      "where": "protruding from the rear of the body at the rump, on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "large, glossy, dark brown to black, hard, ridged beetle elytra-like structure with a central seam and a spiky rear edge, reflecting light",
      "where": "covering the middle of the left side of the torso, over the ribs and flank"
    },
    {
      "part": "plates",
      "looks_like": "multiple smaller glossy dark brown and black chitinous plates of varying shapes - some triangular, some oval, some irregular with spiky edges - with smooth reflective surfaces; several small circular holes with dark rims are visible in the fur beneath and around them, especially along the lower side and neck",
      "where": "scattered across the back, rump, shoulder, neck, chest, and at the joints of all four legs"
    },
    {
      "part": "markings",
      "looks_like": "dense shaggy fur that is medium brown over most of the body, with distinctly lighter cream to off-white fur on the lower chest, belly, and throat, and slightly darker brown on the lower legs and face",
      "where": "covering the entire body, with the lighter coloration on the underside and the darker coloration on the extremities"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
